package com.factory.management.controller;import com.factory.management.dto.request.WarehouseRequest;import com.factory.management.dto.response.*;import com.factory.management.service.ServiceImpl.WarehouseService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController@RequiredArgsConstructor@RequestMapping("${api.prefix}/warehouses")@PreAuthorize("hasAnyRole('ADMIN','DIRECTOR','FINANCE','FACTORY_MANAGER')") public class WarehouseController{private final WarehouseService service;@GetMapping("/all")ApiResponse<List<WarehouseResponse>>all(){return ApiResponse.<List<WarehouseResponse>>builder().result(service.all()).build();}@PostMapping@PreAuthorize("hasAnyRole('ADMIN','FINANCE')")ApiResponse<WarehouseResponse>create(@Valid@RequestBody WarehouseRequest r){return ApiResponse.<WarehouseResponse>builder().result(service.create(r)).build();}@PutMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','FINANCE')")ApiResponse<WarehouseResponse>update(@PathVariable Long id,@Valid@RequestBody WarehouseRequest r){return ApiResponse.<WarehouseResponse>builder().result(service.update(id,r)).build();}@DeleteMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")ApiResponse<Void>delete(@PathVariable Long id){service.delete(id);return ApiResponse.<Void>builder().message("Ngừng sử dụng kho thành công").build();}}
